    """Return "equilateral", "isosceles", "scalene" or "invalid"."""
    # Check if any side is 0 or negative
    if a <= 0 or b <= 0 or c <= 0:
        return "invalid"

    # Check if any side is equal to or longer than the other two added together
    if a + b > c and a + c > b and b + c > a:
        return "scalene"

    # Check if all sides are equal
    if a == b == c:
        return "equilateral"

    # Check if all sides are different
    return "isosceles"

