    if a <= 0 or b <= 0 or c <= 0 or a >= b + c or b >= a + c or c >= a + b:
        return "invalid"

    # Check if all sides are equal
    if a == b == c:
        return "equilateral"

    # Check if exactly two sides are equal
    if a == b or a == c or b == c:
        return "isosceles"

