    result.append(f"{count}{prev_char}")
    return ''.join(result)

def second_largest(nums: list[int]) -> int | None:
    """Return the second largest distinct value in nums, or None if there isn't one."""
    if not nums:
        return None

    s = set(nums)
    distinct_values = list(s)

