from typing import List

def flatten(nested: List) -> List[int]:
    """Return all integers in nested (a list of ints and lists, at any depth) in one list."""
    def flatten_list(item):
        # List is a list of lists
        if isinstance(item, list):
            # Recursively flatten each sublist
            for sub_item in item:
                yield from flatten_list(sub_item)
        # If item is an integer, add it to the result
        else:
            yield item

    # Use generator expression to flatten the nested list
    return list(flatten_list(nested))

